//! NIKL standard curriculum levels (1-6급) for words and grammar (`data/curriculum_words.tsv`,
//! `data/curriculum_grammar.tsv`, generated by `qa/curriculum/xlsx_to_tsv.py`). Source: 국립국어원,
//! 「2017년 국제 통용 한국어 표준 교육과정 적용 연구(4단계)」 어휘·문법 등급 목록, 공공누리 제1유형.
//!
//! Core pack table `curriculum(kind, level, entry_id, grammar_id, form, rank)`: one row per list
//! row; `entry_id` / `grammar_id` point at the matching krdict entry / grammar row, or are NULL when
//! no confident match was found. The list numbers homonyms by 표준국어대사전, so the homonym number
//! is only the last tie-breaker; POS, the 길잡이말 hint and the krdict level decide first.

use anyhow::{bail, Context, Result};
use rusqlite::{params, Connection};
use serde_json::Value;
use std::collections::{HashMap, HashSet};

#[derive(Debug, Clone, PartialEq)]
pub struct CurWord {
    pub rank: i64,
    pub level: i64,
    pub form_raw: String,
    pub headword: String,
    pub homonym: Option<i64>,
    pub pos: String,
    pub hint: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct CurGrammar {
    pub rank: i64,
    pub level: i64,
    pub category: String,
    pub form_raw: String,
    pub form: String,
    pub related: String,
    pub meaning: String,
}

fn rows(tsv: &str, n: usize, what: &str) -> Result<Vec<Vec<String>>> {
    let mut out = Vec::new();
    for (i, line) in tsv.lines().enumerate().filter(|(_, l)| !l.starts_with('#') && !l.trim().is_empty()) {
        let f: Vec<String> = line.split('\t').map(str::to_string).collect();
        if f.len() != n {
            bail!("{what} line {}: {} columns, expected {n}", i + 1, f.len());
        }
        out.push(f);
    }
    Ok(out)
}

pub fn parse_words(tsv: &str) -> Result<Vec<CurWord>> {
    rows(tsv, 7, "curriculum_words.tsv")?
        .into_iter()
        .map(|f| {
            Ok(CurWord {
                rank: f[0].parse().context("rank")?,
                level: f[1].parse().context("level")?,
                form_raw: f[2].clone(),
                headword: f[3].clone(),
                homonym: f[4].parse().ok(),
                pos: f[5].clone(),
                hint: f[6].clone(),
            })
        })
        .collect()
}

pub fn parse_grammar(tsv: &str) -> Result<Vec<CurGrammar>> {
    rows(tsv, 7, "curriculum_grammar.tsv")?
        .into_iter()
        .map(|f| {
            Ok(CurGrammar {
                rank: f[0].parse().context("rank")?,
                level: f[1].parse().context("level")?,
                category: f[2].clone(),
                form_raw: f[3].clone(),
                form: f[4].clone(),
                related: f[5].clone(),
                meaning: f[6].clone(),
            })
        })
        .collect()
}

pub fn builtin_words() -> Vec<CurWord> {
    parse_words(include_str!("../data/curriculum_words.tsv")).expect("curriculum_words.tsv parses")
}

pub fn builtin_grammar() -> Vec<CurGrammar> {
    parse_grammar(include_str!("../data/curriculum_grammar.tsv")).expect("curriculum_grammar.tsv parses")
}

// ---------------------------------------------------------------- words

/// A krdict word entry that may match a list row.
#[derive(Debug, Clone)]
pub struct WordCand {
    pub id: i64,
    pub homonym: Option<i64>,
    pub pos: String,
    pub level: Option<i64>,
    /// Definitions, notes and example sentences, for the hint check.
    pub text: String,
}

const ALT_SEPS: [char; 5] = ['/', '∙', '·', '‧', '・'];

fn is_sep(c: char) -> bool {
    matches!(c, '/' | '∙' | '·' | '‧' | '・' | '.' | ' ' | ',')
}

/// How well a krdict `pos` fits one list POS token (0 = not at all, 100 = exactly).
fn pos_fit(token: &str, pos: &str) -> u32 {
    match (token, pos) {
        ("명사", "noun") | ("의존명사", "bound noun") | ("동사", "verb") | ("형용사", "adjective") | ("부사", "adverb") => 100,
        ("대명사", "pronoun") | ("수사", "numeral") | ("관형사", "determiner") | ("감탄사", "interjection") | ("접사", "affix") => 100,
        ("동사", "auxiliary verb") | ("형용사", "auxiliary adjective") | ("의존명사", "noun") | ("명사", "bound noun") => 60,
        ("줄어든말", _) => 30,
        _ => 0,
    }
}

fn best_pos_fit(list_pos: &str, pos: &str) -> u32 {
    list_pos.split(is_sep).filter(|t| !t.is_empty()).map(|t| pos_fit(t, pos)).max().unwrap_or(0)
}

/// krdict's three levels against the six NIKL grades (1-2 / 3-4 / 5-6).
fn level_fits(cur: i64, krdict: Option<i64>) -> bool {
    krdict.is_some_and(|k| (cur + 1) / 2 == k)
}

/// 0..=10: how much of the 길잡이말 hint shows up in the entry's text (whole phrase = 10, else one
/// point per content word whose stem occurs, up to 3).
fn hint_score(hint: &str, headword: &str, text: &str) -> u32 {
    let hint = hint.trim();
    if hint.is_empty() {
        return 0;
    }
    for alt in hint.split('/') {
        let alt = alt.trim().trim_end_matches(['.', '다']);
        if alt.chars().count() >= 3 && text.contains(alt) {
            return 10;
        }
    }
    let mut n = 0;
    for t in hint.split(|c: char| is_sep(c) || c == '?') {
        let cs: Vec<char> = t.chars().collect();
        if cs.len() < 2 || t.contains(headword) || headword.contains(t) {
            continue;
        }
        let stem: String = cs[..cs.len().max(3) - 1].iter().collect();
        if text.contains(&stem) {
            n += 1;
        }
    }
    n.min(3)
}

/// Pick the krdict entry for a list row among `cands` (all with the row's headword). `claimed`
/// holds entries already given to an earlier row, so a second row of the same headword (the list's
/// homonyms) prefers the other entry.
pub fn match_word(w: &CurWord, cands: &[WordCand], claimed: &HashSet<i64>) -> Option<i64> {
    let mut best: Option<(i64, i64, u32, u32)> = None; // (score, id, pos, hint)
    for c in cands {
        let pos = best_pos_fit(&w.pos, &c.pos);
        let hint = hint_score(&w.hint, &w.headword, &c.text);
        let mut score = pos as i64 + 5 * hint as i64;
        if level_fits(w.level, c.level) {
            score += 8;
        }
        if w.homonym.is_some() && w.homonym == c.homonym {
            score += 3;
        }
        if claimed.contains(&c.id) {
            score -= 15;
        }
        if best.is_none_or(|b| score > b.0 || (score == b.0 && c.id < b.1)) {
            best = Some((score, c.id, pos, hint));
        }
    }
    let (_, id, pos, hint) = best?;
    // a POS fit, or a wrong/unknown POS rescued by the hint, or the only entry of that headword
    (pos >= 30 || hint >= 3 || cands.len() == 1).then_some(id)
}

/// Suffixes tried when the list's bare noun has no krdict entry ("다양" -> 다양하다, "상반" -> 상반되다).
const DERIVED_SUFFIXES: [&str; 2] = ["하다", "되다"];

/// A list row whose bare headword matched nothing: the verb or adjective derived from it
/// (X하다, X되다; krdict has no entry for the stem itself). The suffix the 길잡이말 hint uses
/// ("주장이 상반되다") is tried first, else 하다 before 되다. Only noun / verb / adjective rows
/// qualify, the candidate must be a verb or adjective, and among homonyms the claimed set, the
/// krdict level and the hint decide as in [`match_word`].
pub fn match_word_derived(w: &CurWord, by_hw: &HashMap<String, Vec<WordCand>>, claimed: &HashSet<i64>) -> Option<i64> {
    if !w.pos.split(is_sep).any(|t| matches!(t, "명사" | "동사" | "형용사")) {
        return None;
    }
    let mut sufs = DERIVED_SUFFIXES.to_vec();
    sufs.sort_by_key(|s| !w.hint.contains(&format!("{}{s}", w.headword)));
    for suf in sufs {
        let hw = format!("{}{suf}", w.headword);
        let Some(cands) = by_hw.get(&hw) else { continue };
        let best = cands
            .iter()
            .filter(|c| matches!(c.pos.as_str(), "verb" | "adjective"))
            .max_by_key(|c| (!claimed.contains(&c.id), level_fits(w.level, c.level), hint_score(&w.hint, &hw, &c.text), std::cmp::Reverse(c.id)));
        if let Some(c) = best {
            return Some(c.id);
        }
    }
    None
}

// ---------------------------------------------------------------- grammar

/// A row of the core `grammar` table.
#[derive(Debug, Clone)]
pub struct GrammarCand {
    pub id: i64,
    pub entry_id: Option<i64>,
    pub pattern: String,
    pub category: String,
}

/// Comparison key of a pattern: no hyphens, spaces, digits, parentheses or commas.
pub fn grammar_key(s: &str) -> String {
    let mut out = String::new();
    let mut depth = 0;
    for c in s.chars() {
        match c {
            '(' => depth += 1,
            ')' => depth = (depth - 1).max(0),
            _ if depth > 0 => {}
            '-' | '–' | '~' | ',' | ' ' | '\u{a0}' | '\'' | '\u{ad}' => {}
            c if c.is_ascii_digit() => {}
            c => out.push(c),
        }
    }
    out
}

/// The forms a list row stands for: its own form first, then the related ones (the `<반의>` /
/// `<유의>` antonyms and synonyms are different expressions and are dropped).
pub fn grammar_forms(g: &CurGrammar) -> Vec<String> {
    let mut v = vec![g.form_raw.clone()];
    let rel = g.related.split('<').next().unwrap_or("");
    v.extend(rel.split(',').map(str::trim).filter(|s| !s.is_empty()).map(str::to_string));
    v
}

fn category_fits(list_cat: &str, cat: &str) -> bool {
    matches!(
        (list_cat, cat),
        ("조사", "Particles")
            | ("연결어미", "Connective endings")
            | ("종결어미", "Final endings")
            | ("선어말어미", "Pre-final endings" | "Final endings")
            | ("전성어미", "Nominal/adnominal endings")
            | ("표현", "Expressions")
    )
}

/// Keys a form is looked up under: itself, "...하여" as the dictionary form "...하다" (the list
/// writes `으로 인하여` where krdict has `으로 인하다`), and, for an expression, without its
/// closing 에 (the list's `-기 때문에`, `-는 탓에` are krdict's `-기 때문`, `-는 탓`).
fn lookup_keys(form: &str, category: &str) -> Vec<String> {
    let k = grammar_key(form);
    let mut v = vec![k.clone()];
    if let Some(stem) = k.strip_suffix("하여") {
        v.push(format!("{stem}하다"));
    }
    if category == "표현" {
        if let Some(stem) = k.strip_suffix('에').filter(|s| s.chars().count() >= 2) {
            v.push(stem.to_string());
        }
    }
    v
}

/// Hand-checked spelling variants: (list category, list form key, krdict pattern key). Each target
/// is a krdict row of the same pattern whose own text says so (`-으려야` "구어에서 -을래야로
/// 발음하기도 한다"; krdict's `그려` is the particle that follows an ending, `-네그려`, which the
/// list files under 종결어미). Tried only when the ordinary lookup finds nothing.
pub const GRAMMAR_ALIASES: &[(&str, &str, &str)] = &[("연결어미", "을래야", "으려야"), ("연결어미", "ㄹ래야", "려야"), ("종결어미", "그려", "그려")];

/// List rows that krdict describes as a sense of a word entry rather than as a grammar row:
/// (list form key, krdict headword, homonym, pos). `에 따라` is the 8th sense of 따르다 (1이 2에
/// 따르다, "주로 '따라(서)'로 쓴다"), `에 의하여` of 의하다 (1이 2에 의하다), `이 아니다` of 아니다
/// (1이 2가 아니다), `-어 치우다` is the auxiliary verb 치우다 ("'-어 치우다'로 쓴다"). The
/// curriculum row links to the entry only (`grammar_id` stays NULL: there is no grammar row).
pub const GRAMMAR_WORD_LINKS: &[(&str, &str, Option<i64>, &str)] = &[
    ("에따라", "따르다", Some(1), "verb"),
    ("에의하여", "의하다", None, "verb"),
    ("이아니다", "아니다", None, "adjective"),
    ("어치우다", "치우다", None, "auxiliary verb"),
];

/// The word-entry link of a list row (see [`GRAMMAR_WORD_LINKS`]).
pub fn grammar_word_link(g: &CurGrammar) -> Option<(&'static str, Option<i64>, &'static str)> {
    let k = grammar_key(&g.form_raw);
    GRAMMAR_WORD_LINKS.iter().find(|l| l.0 == k).map(|l| (l.1, l.2, l.3))
}

/// Key -> grammar rows. A pattern with alternatives (`와/과`, `으로/로`) is indexed under each one.
pub fn grammar_index(rows: &[GrammarCand]) -> HashMap<String, Vec<usize>> {
    let mut by_key: HashMap<String, Vec<usize>> = HashMap::new();
    for (i, r) in rows.iter().enumerate() {
        if r.category != "Affixes" {
            for alt in r.pattern.split('/') {
                let v = by_key.entry(grammar_key(alt)).or_default();
                if !v.contains(&i) {
                    v.push(i);
                }
            }
        }
    }
    by_key
}

/// Pick the grammar row for a list row: the main form is tried before the related forms, and
/// within a form a row of the right category (and the same leading hyphen) wins. A form never
/// lands on a particle unless the list row is one (`다가` the particle vs `-다가` the ending).
pub fn match_grammar(g: &CurGrammar, rows: &[GrammarCand], by_key: &HashMap<String, Vec<usize>>) -> Option<usize> {
    let forms = grammar_forms(g);
    for form in &forms {
        let hyphen = form.trim_start().starts_with('-');
        for key in lookup_keys(form, &g.category) {
            let Some(idx) = by_key.get(&key) else { continue };
            let best = idx
                .iter()
                .copied()
                .filter(|&i| g.category == "조사" || rows[i].category != "Particles")
                .max_by_key(|&i| {
                    let r = &rows[i];
                    ((category_fits(&g.category, &r.category) as u8) * 2 + (r.pattern.starts_with('-') == hyphen) as u8, std::cmp::Reverse(i))
                });
            if best.is_some() {
                return best;
            }
        }
    }
    for form in &forms {
        let key = grammar_key(form);
        for (cat, from, to) in GRAMMAR_ALIASES {
            if *cat == g.category && *from == key {
                if let Some(i) = by_key.get(*to).and_then(|v| v.iter().copied().min()) {
                    return Some(i);
                }
            }
        }
    }
    None
}

// ---------------------------------------------------------------- build step

fn cand_text(data: &str) -> String {
    let Ok(v) = serde_json::from_str::<Value>(data) else { return String::new() };
    let mut t = String::new();
    for s in v.get("senses").and_then(Value::as_array).into_iter().flatten() {
        for k in ["ko_def", "note", "pattern"] {
            if let Some(x) = s.get(k).and_then(Value::as_str) {
                t.push_str(x);
                t.push('\n');
            }
        }
        for x in s.get("examples").and_then(Value::as_array).into_iter().flatten() {
            if let Some(x) = x.get("ko").and_then(Value::as_str) {
                t.push_str(x);
                t.push('\n');
            }
        }
    }
    t
}

fn alternates(w: &CurWord) -> Vec<String> {
    let mut seen = HashSet::new();
    std::iter::once(w.headword.clone())
        .chain(w.form_raw.split(ALT_SEPS).map(|p| p.trim_end_matches(|c: char| c.is_ascii_digit()).to_string()))
        .filter(|h| !h.is_empty() && seen.insert(h.clone()))
        .collect()
}

/// Create and fill `curriculum`; returns (words matched, words total, grammar matched, grammar total).
/// Needs the `entries` and `grammar` tables to be filled.
pub fn build_table(conn: &Connection) -> Result<(usize, usize, usize, usize)> {
    let words = builtin_words();
    let grammar = builtin_grammar();
    conn.execute_batch(
        "CREATE TABLE curriculum (kind TEXT NOT NULL, level INTEGER NOT NULL, entry_id INTEGER, grammar_id INTEGER, form TEXT NOT NULL, rank INTEGER NOT NULL);",
    )?;

    let mut wanted: HashSet<String> = words.iter().flat_map(alternates).collect();
    wanted.extend(words.iter().flat_map(|w| DERIVED_SUFFIXES.iter().map(move |s| format!("{}{s}", w.headword))));
    wanted.extend(GRAMMAR_WORD_LINKS.iter().map(|l| l.1.to_string()));
    let mut by_hw: HashMap<String, Vec<WordCand>> = HashMap::new();
    {
        let mut st = conn.prepare("SELECT id, headword, homonym, pos, level, data FROM entries WHERE source='krdict' AND kind='word' ORDER BY id")?;
        let mut q = st.query([])?;
        while let Some(r) = q.next()? {
            let hw: String = r.get(1)?;
            if !wanted.contains(&hw) {
                continue;
            }
            let data: String = r.get(5)?;
            by_hw.entry(hw).or_default().push(WordCand {
                id: r.get(0)?,
                homonym: r.get(2)?,
                pos: r.get::<_, Option<String>>(3)?.unwrap_or_default(),
                level: r.get(4)?,
                text: cand_text(&data),
            });
        }
    }
    let mut claimed: HashSet<i64> = HashSet::new();
    let (mut nw, mut ng) = (0, 0);
    let mut ins = conn.prepare("INSERT INTO curriculum(kind,level,entry_id,grammar_id,form,rank) VALUES(?,?,?,?,?,?)")?;
    for w in &words {
        let id = alternates(w)
            .iter()
            .find_map(|hw| by_hw.get(hw).and_then(|c| match_word(w, c, &claimed)))
            .or_else(|| match_word_derived(w, &by_hw, &claimed));
        if let Some(i) = id {
            claimed.insert(i);
            nw += 1;
        }
        ins.execute(params!["word", w.level, id, Option::<i64>::None, w.form_raw, w.rank])?;
    }

    let rows_g: Vec<GrammarCand> = {
        let mut st = conn.prepare("SELECT id, entry_id, pattern, category FROM grammar ORDER BY id")?;
        let v = st
            .query_map([], |r| Ok(GrammarCand { id: r.get(0)?, entry_id: r.get(1)?, pattern: r.get(2)?, category: r.get(3)? }))?
            .collect::<std::result::Result<_, _>>()?;
        v
    };
    let by_key = grammar_index(&rows_g);
    for g in &grammar {
        let m = match_grammar(g, &rows_g, &by_key).map(|i| &rows_g[i]);
        let mut entry_id = m.and_then(|r| r.entry_id);
        if m.is_none() {
            // a sense of a word entry (`에 따라` = 따르다), see GRAMMAR_WORD_LINKS
            entry_id = grammar_word_link(g).and_then(|(hw, hom, pos)| {
                by_hw.get(hw).and_then(|c| c.iter().filter(|c| c.pos == pos && (hom.is_none() || c.homonym == hom)).map(|c| c.id).min())
            });
        }
        if m.is_some() || entry_id.is_some() {
            ng += 1;
        } else {
            log::warn!("curriculum grammar without a match: {}급 {} {}", g.level, g.category, g.form_raw);
        }
        ins.execute(params!["grammar", g.level, entry_id, m.map(|r| r.id), g.form_raw, g.rank])?;
    }
    conn.execute_batch("CREATE INDEX curriculum_kind_level ON curriculum(kind, level);")?;
    Ok((nw, words.len(), ng, grammar.len()))
}
